    # and extend the center ray in that direction to the edge.
    row_rails = [r for r in range(h) if sum(v == 2 for v in grid[r]) >= w * 0.65]
    col_rails = [c for c in range(w) if sum(grid[r][c] == 2 for r in range(h)) >= h * 0.65]

