    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])

    # Find each 3x3 marker: a ring of 3s around a 2 at a grid-line crossing.
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] != 2:
                continue
            if not all(grid[r + dr][c + dc] == 3
                       for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                       if (dr, dc) != (0, 0)):
                continue

            # Rays travel along the other axis of the regular 2-grid.
            col_rail = sum(grid[rr][c] == 2 for rr in range(h)) > h / 2
            row_rail = sum(grid[r][cc] == 2 for cc in range(w)) > w / 2

            if col_rail:
                # Marker centered on a vertical rail: run horizontally right.
                for cc in range(c + 2, w):
                    if grid[r][cc] != 2:
                        out[r][cc] = 1
            elif row_rail:
                # Marker centered on a horizontal rail: run vertically down.
                for rr in range(r + 2, h):
                    if grid[rr][c] != 2:
                        out[rr][c] = 1

            # From each marker, project its ring to the next parallel rail
            # encountered in the ray direction. The 2 at its center is retained.
            if col_rail:
                rails = [cc for cc in range(c + 1, w)
                         if sum(grid[rr][cc] == 2 for rr in range(h)) > h / 2]
                if rails:
                    tc = min(rails)
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
                            if (dr, dc) != (0, 0):
                                rr, cc = r + dr, tc + dc
                                if 0 <= rr < h and 0 <= cc < w:
                                    out[rr][cc] = 1
            elif row_rail:
                rails = [rr for rr in range(r + 1, h)
                         if sum(grid[rr][cc] == 2 for cc in range(w)) > w / 2]
                if rails:
                    tr = min(rails)
                    for dr in (-1, 0, 1):
                        for dc in (-1, 0, 1):
